package pt.realmmarriage.test;
import com.google.gson.*;
import java.nio.file.*;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.gametest.framework.*;
import net.minecraft.nbt.*;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.item.*;
import net.minecraft.world.item.component.CustomData;
import net.minecraft.world.level.block.state.properties.DoubleBlockHalf;
import net.minecraft.world.level.storage.LevelResource;
import net.neoforged.neoforge.gametest.GameTestHolder;
import pt.realmmarriage.api.*;
import pt.realmmarriage.block.*;
import pt.realmmarriage.compat.*;
import pt.realmmarriage.data.MarriageData;
import pt.realmmarriage.domain.MarriageLedger;
import pt.realmmarriage.domain.MarriageLedger.*;
import pt.realmmarriage.service.*;
@GameTestHolder("realmmarriage")
@net.neoforged.neoforge.gametest.PrefixGameTestTemplate(false)
public final class MarriageGameTests {
    private static MarriageActors group(GameTestHelper h){var a=new MarriageActors(h);a.actor(50000);a.actor(30000);a.actor(10000);a.place(a.actors.getFirst());return a;}
    private static void assertDenied(Runnable action){try{action.run();throw new AssertionError("Unauthorised action was accepted");}catch(IllegalStateException expected){}}
    @GameTest(template="marriage_empty",templateNamespace="realmmarriage",batch="marriage-block") public static void physicalAltarHasTwoSupportedHalves(GameTestHelper h){try(var a=group(h)){var state=h.getLevel().getBlockState(a.altar);h.assertTrue(state.is(BlockRegistry.ALTAR.get())&&state.getValue(WeddingAltarBlock.HALF)==DoubleBlockHalf.LOWER,"Lower altar missing");h.assertTrue(BlockRegistry.ALTAR.get().validStructure(h.getLevel(),a.altar),"Upper piece/support not validated");h.assertTrue(MarriageService.station(a.actors.getFirst()),"Native placement did not open a physical session");}h.succeed();}
    @GameTest(template="marriage_empty",templateNamespace="realmmarriage",batch="marriage-block") public static void brokenOrRemoteAltarDoesNotAuthoriseFinances(GameTestHelper h){try(var a=group(h)){var p=a.actors.getFirst();h.getLevel().destroyBlock(a.altar.above(),false);h.assertTrue(!MarriageService.station(p),"Broken upper piece still authorised");p.setPos(p.getX()+30,p.getY(),p.getZ());h.assertTrue(!MarriageService.station(p),"Remote physical session accepted");}h.succeed();}
    @GameTest(template="marriage_empty",templateNamespace="realmmarriage",batch="marriage-basic") public static void actualServerSettlesFreeSeparateMarriage(GameTestHelper h){try(var a=group(h)){var u=a.married(Mode.SEPARATE,0);h.assertTrue(u.phase==Phase.MARRIED&&!u.priestAccepted&&u.ringTokens.size()==2,"Official record or temporary authority incorrect");if(WalletBridge.loaded())h.assertTrue(WalletBridge.balance(a.actors.get(0))==50000&&WalletBridge.balance(a.actors.get(1))==30000,"Separate wallets changed");}System.out.println("MARRIAGE_SEPARATE_PASSED");h.succeed();}
    @GameTest(template="marriage_empty",templateNamespace="realmmarriage",batch="marriage-basic") public static void serverRejectsAProposalWithoutAnActualHeldRing(GameTestHelper h){try(var a=group(h)){var p=a.actors.get(0);p.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);assertDenied(()->MarriageService.propose(p,a.actors.get(1)));}h.succeed();}
    @GameTest(template="marriage_empty",templateNamespace="realmmarriage",batch="marriage-basic") public static void proposalCooldownSurvivesSessionLogout(GameTestHelper h){try(var a=group(h)){var p=a.actors.get(0);var target=a.actors.get(1);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(BlockRegistry.ENGAGEMENT_RING.get()));MarriageService.propose(p,target);var d=MarriageData.get(p.getServer());d.ledger.cancel(d.ledger.current(p.getUUID()),p.getUUID(),System.currentTimeMillis());MarriageService.logout(p.getUUID());assertDenied(()->MarriageService.propose(p,target));}h.succeed();}
    @GameTest(template="marriage_empty",templateNamespace="realmmarriage",batch="marriage-basic") public static void absenceSuspendsTheCeremonyWithoutFunding(GameTestHelper h){try(var a=group(h)){var d=MarriageData.get(h.getLevel().getServer());var u=a.committing(Mode.SEPARATE,0);u.phase=Phase.INTRODUCTION;a.actors.get(1).setPos(a.altar.getX()+40,a.altar.getY(),a.altar.getZ());h.assertTrue(!MarriageService.present(h.getLevel().getServer(),u,u.dimension,a.altar,d.ledger.settings,true),"Missing spouse accepted");d.ledger.suspend(u,"absence",System.currentTimeMillis());h.assertTrue(u.phase==Phase.SUSPENDED&&!u.fundedA&&!u.fundedB,"Suspension funded or completed a wedding");}h.succeed();}
    @GameTest(template="marriage_empty",templateNamespace="realmmarriage",batch="marriage-basic") public static void restartSuspendsCeremoniesBeforeAnyLogin(GameTestHelper h){try(var a=group(h)){var u=a.committing(Mode.SEPARATE,0);u.phase=Phase.OBJECTIONS;MarriageService.started(h.getLevel().getServer());h.assertTrue(u.phase==Phase.SUSPENDED&&u.continueVotes.isEmpty(),"Restart resumed automatically");}h.succeed();}
    @GameTest(template="marriage_empty",templateNamespace="realmmarriage",batch="marriage-basic") public static void documentsRequireServerRegistryTokens(GameTestHelper h){try(var a=group(h)){var u=a.married(Mode.SEPARATE,0);var p=a.actors.getFirst();ItemStack real=MarriageService.documentStack(u,p.getUUID(),true);h.assertTrue(Boolean.TRUE.equals(MarriageService.document(p,real).get("authentic")),"Real certificate rejected");CompoundTag custom=real.get(DataComponents.CUSTOM_DATA).copyTag();custom.getCompound("realmmarriage").putUUID("owner",a.actors.get(2).getUUID());real.set(DataComponents.CUSTOM_DATA,CustomData.of(custom));assertDenied(()->MarriageService.document(p,real));assertDenied(()->MarriageService.document(p,new ItemStack(BlockRegistry.CERTIFICATE.get())));}h.succeed();}
    @GameTest(template="marriage_empty",templateNamespace="realmmarriage",batch="marriage-basic") public static void claimingDocumentsPersistsBeforeASecondClaim(GameTestHelper h){try(var a=group(h)){var u=a.married(Mode.SEPARATE,0);var p=a.actors.getFirst();MarriageService.claimDocuments(p,u);h.assertTrue(u.claimed.contains(p.getUUID()),"Claim not recorded");assertDenied(()->MarriageService.claimDocuments(p,u));long docs=p.getInventory().items.stream().filter(s->s.is(BlockRegistry.CERTIFICATE.get())||s.is(BlockRegistry.WEDDING_RING.get())).count();h.assertTrue(docs==2,"Claim duplicated documents");}h.succeed();}
    @GameTest(template="marriage_empty",templateNamespace="realmmarriage",batch="marriage-basic") public static void aFullInventoryDoesNotConsumeTheDocumentEntitlement(GameTestHelper h){try(var a=group(h)){var u=a.married(Mode.SEPARATE,0);var p=a.actors.getFirst();for(int i=0;i<36;i++)p.getInventory().setItem(i,new ItemStack(Items.STONE,64));assertDenied(()->MarriageService.claimDocuments(p,u));h.assertTrue(!u.claimed.contains(p.getUUID()),"Failed claim lost documents");}h.succeed();}
    @GameTest(template="marriage_empty",templateNamespace="realmmarriage",batch="marriage-basic") public static void publicCivilStatusRespectsSpousePrivacy(GameTestHelper h)throws Exception{try(var a=group(h)){var u=a.married(Mode.SEPARATE,0);var d=MarriageData.get(h.getLevel().getServer());d.ledger.citizen(u.a).publicSpouse=false;JsonObject publicView=JsonParser.parseString(MarriageApi.statusJson(h.getLevel().getServer(),u.a,a.actors.get(2).getUUID())).getAsJsonObject();h.assertTrue(publicView.get("status").getAsString().equals("MARRIED")&&!publicView.has("name"),"Private spouse leaked");JsonObject own=JsonParser.parseString(MarriageApi.statusJson(h.getLevel().getServer(),u.a,u.a)).getAsJsonObject();h.assertTrue(own.has("name"),"Owner lost spouse access");if(net.neoforged.fml.ModList.get().isLoaded("realmidentity")){Map<String,Object> view=new HashMap<>();Class<?> bridge=Class.forName("pt.realmidentity.compat.MarriageBridge");var method=bridge.getMethod("addTo",Map.class,net.minecraft.server.MinecraftServer.class,UUID.class,UUID.class);method.invoke(null,view,h.getLevel().getServer(),u.a,a.actors.get(2).getUUID());h.assertTrue(!((JsonObject)view.get("marriage")).has("name"),"Identity bridge leaked the private spouse to a viewer");method.invoke(null,view,h.getLevel().getServer(),u.a,u.a);h.assertTrue(((JsonObject)view.get("marriage")).has("name"),"Identity owner consultation lost spouse access");}}h.succeed();}
    @GameTest(template="marriage_empty",templateNamespace="realmmarriage",batch="marriage-basic") public static void snapshotsNeverExposeDocumentTokens(GameTestHelper h){try(var a=group(h)){var u=a.married(Mode.SEPARATE,0);String json=MarriageService.snapshot(a.actors.get(2),"");for(UUID token:u.ringTokens.values())h.assertTrue(!json.contains(token.toString()),"Ring token leaked");for(UUID token:u.certificateTokens.values())h.assertTrue(!json.contains(token.toString()),"Certificate token leaked");}h.succeed();}
    @GameTest(template="marriage_empty",templateNamespace="realmmarriage",batch="marriage-finance") public static void jointMoneyAndOddFeeConserveEveryCent(GameTestHelper h){if(!WalletBridge.loaded()||!CrownBridge.loaded()){h.succeed();return;}try(var a=group(h)){long before=MarriageActors.bank(h.getLevel().getServer());var u=a.married(Mode.JOINT,3001);h.assertTrue(WalletBridge.balance(a.actors.get(0))==0&&WalletBridge.balance(a.actors.get(1))==0&&u.balance==76999,"Joint consolidation incorrect");h.assertTrue(MarriageActors.bank(h.getLevel().getServer())==before+3001,"Treasury did not receive exactly the fee");CrownBridge.transfer(h.getLevel().getServer(),MarriageLedger.key(u.id+":wedding-fee"),u.a,3001);h.assertTrue(MarriageActors.bank(h.getLevel().getServer())==before+3001,"Fee replay duplicated public money");}System.out.println("MARRIAGE_JOINT_CROWN_PASSED");h.succeed();}
    @GameTest(template="marriage_empty",templateNamespace="realmmarriage",batch="marriage-finance") public static void sharedAccountPreservesPersonalWalletsAndDividesOfflineCredit(GameTestHelper h){if(!WalletBridge.loaded()){h.succeed();return;}try(var a=group(h)){var u=a.married(Mode.SHARED,0);var p=a.actors.get(0);var q=a.actors.get(1);MarriageService.money(p,u,"deposit",10000);MarriageService.money(q,u,"withdraw",2500);h.assertTrue(WalletBridge.balance(p)==40000&&WalletBridge.balance(q)==32500&&u.balance==7500,"Shared account transfer incorrect");var d=MarriageData.get(p.getServer());a.online.remove(q);a.byId.remove(q.getUUID());d.ledger.divorce(u,p.getUUID(),System.currentTimeMillis());d.persist(p.getServer());h.assertTrue(d.ledger.citizen(q.getUUID()).credit()==3750,"Offline spouse lost their share");MarriageService.claimCredits(p,3750);h.assertTrue(WalletBridge.balance(p)==43750,"Own divorce credit not collected once");assertDenied(()->MarriageService.claimCredits(p,1));}System.out.println("MARRIAGE_SHARED_DIVORCE_PASSED");h.succeed();}
    @GameTest(template="marriage_empty",templateNamespace="realmmarriage",batch="marriage-finance") public static void sharedPaymentsRequireTheRegisteredConsumerInstance(GameTestHelper h){if(!WalletBridge.loaded()){h.succeed();return;}try(var a=group(h)){var u=a.married(Mode.SHARED,0);var p=a.actors.getFirst();MarriageService.money(p,u,"deposit",5000);var consumer=MarriagePayments.register("qa-"+UUID.randomUUID());UUID receipt=UUID.randomUUID();assertDenied(()->MarriagePayments.reserve(new MarriagePayments.Consumer(consumer.id()),p,receipt,u.id,1000));MarriagePayments.reserve(consumer,p,receipt,u.id,1000);MarriagePayments.reserve(consumer,p,receipt,u.id,1000);h.assertTrue(u.balance==4000,"Payment escrow duplicated");MarriagePayments.refund(consumer,p.getServer(),receipt);h.assertTrue(u.balance==5000,"Payment refund lost money");}h.succeed();}
    @GameTest(template="marriage_empty",templateNamespace="realmmarriage",batch="marriage-finance") public static void corruptedOrMissingFinancialIntentFailsClosed(GameTestHelper h){try(var a=group(h)){var u=a.married(Mode.SEPARATE,0);var d=MarriageData.get(h.getLevel().getServer());d.ledger.op(UUID.randomUUID(),u.a,u,Kind.WITHDRAW,1,0,"",System.currentTimeMillis());CompoundTag root=d.save(new CompoundTag(),h.getLevel().registryAccess());assertDenied(()->MarriageData.load(root,h.getLevel().registryAccess()));d.ledger.operations.entrySet().removeIf(e->e.getValue().state==OpState.PREPARED);}h.succeed();}
    @GameTest(template="marriage_empty",templateNamespace="realmmarriage",batch="marriage-recovery") public static void aSavedIntentRecoversOnceAfterRegistryReload(GameTestHelper h)throws java.io.IOException{if(!WalletBridge.loaded()){h.succeed();return;}try(var a=group(h)){var u=a.married(Mode.SHARED,0);var p=a.actors.getFirst();MarriageService.money(p,u,"deposit",5000);var d=MarriageData.get(p.getServer());UUID id=UUID.randomUUID();CompoundTag intent=WalletJournal.intent(p,id,1000,null);d.ledger.op(id,p.getUUID(),u,Kind.WITHDRAW,1000,0,"",System.currentTimeMillis());d.ledger.withdrawReserve(u,p.getUUID(),1000);d.journals.put(p.getUUID(),intent);d.persist(p.getServer());Path file=p.getServer().getWorldPath(LevelResource.ROOT).resolve("data/realm_marriage.dat");MarriageData restored=MarriageData.load(NbtIo.readCompressed(file,NbtAccounter.create(64000000)).getCompound("data"),p.registryAccess());p.getServer().overworld().getDataStorage().set(MarriageData.KEY,restored);WalletJournal.recover(p);long balance=WalletBridge.balance(p);WalletJournal.recover(p);h.assertTrue(balance==46000&&WalletBridge.balance(p)==balance&&restored.ledger.union(u.id).balance==4000,"Recovered intent replayed or lost money");}System.out.println("MARRIAGE_WALLET_RECOVERY_PASSED");h.succeed();}
    @GameTest(template="marriage_empty",templateNamespace="realmmarriage",batch="marriage-authority") public static void optionalAdministratorProviderIsAuthoritative(GameTestHelper h){try(var a=group(h)){var p=a.actors.getFirst();MarriagePermissions.Provider provider=player->player.getUUID().equals(p.getUUID());MarriagePermissions.register(provider);try{h.assertTrue(MarriagePermissions.admin(p)&&!MarriagePermissions.admin(a.actors.get(1)),"Delegated provider ignored");assertDenied(()->MarriagePermissions.unregister(player->true));}finally{MarriagePermissions.unregister(provider);}}h.succeed();}
    @GameTest(template="marriage_empty",templateNamespace="realmmarriage",batch="marriage-council") public static void weddingFeeAuthorityRequiresLiveSwornMandate(GameTestHelper h){if(!MarriageCouncilFixture.loaded()){h.succeed();return;}try(var a=group(h);var council=new MarriageCouncilFixture(h.getLevel().getServer())){long now=Math.max(System.currentTimeMillis(),MarriageData.get(h.getLevel().getServer()).ledger.highWater);var p=a.actors.getFirst();var other=a.actors.get(1);council.mandate(p.getUUID(),now-3600000,now+3600000,0);h.assertTrue(!MarriageService.governor(p),"Unsworn mandate granted fee powers");council.claim(now-1000);h.assertTrue(MarriageService.governor(p)&&!MarriageService.governor(other),"Sworn authority incorrect");council.expire(now-1);h.assertTrue(!MarriageService.governor(p),"Expired President retained powers");council.mandate(other.getUUID(),now-10000,now+3600000,now-1000);h.assertTrue(MarriageService.governor(other)&&!MarriageService.governor(p),"Succession retained old powers");}System.out.println("MARRIAGE_COUNCIL_PASSED");h.succeed();}
}
